import SwiftUI
import Photos

struct StorageAnalysisView: View {
    @ObservedObject var language: LanguageStore
    @ObservedObject var backup: BackupEngine
    @StateObject private var intelligence = StorageIntelligence()
    @StateObject private var cleaner = ProtectedSpaceCleaner()
    @State private var selectedCategory: StorageInsightItem.Kind?
    @State private var selectedIDs = Set<String>()
    @State private var showLargest = false
    @State private var showFreeOffer = false

    private var usedBytes: Int64 { max(0, intelligence.deviceCapacityBytes - intelligence.deviceAvailableBytes) }
    private var usedFraction: Double { intelligence.deviceCapacityBytes > 0 ? min(1, Double(usedBytes) / Double(intelligence.deviceCapacityBytes)) : 0 }
    private var selectedBytes: Int64 { intelligence.items.filter { selectedIDs.contains($0.id) }.reduce(0) { $0 + $1.bytes } }
    private var freeSize: String { size(cleaner.selectedBytes) }

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 18) {
                Text(language.text("Storage analysis", "Analyse du stockage")).font(.system(size: 34, weight: .bold, design: .rounded))
                Text(language.text("Find what takes the most space, protect exactly what you choose, then free only verified copies.", "Trouvez ce qui prend le plus de place, protégez exactement ce que vous choisissez, puis libérez uniquement les copies vérifiées.")).foregroundStyle(.secondary)
                VStack(alignment: .leading, spacing: 14) {
                    HStack { Label(language.text("This iPhone", "Cet iPhone"), systemImage: "iphone").font(.headline); Spacer(); Text(size(intelligence.deviceCapacityBytes)).fontWeight(.bold) }
                    ProgressView(value: usedFraction).tint(.blue)
                    HStack { VStack(alignment:.leading,spacing:3){Text(language.text("Used","Utilisé")).font(.caption).foregroundStyle(.secondary);Text(size(usedBytes)).font(.title3.bold())};Spacer();VStack(alignment:.trailing,spacing:3){Text(language.text("Available","Disponible")).font(.caption).foregroundStyle(.secondary);Text(size(intelligence.deviceAvailableBytes)).font(.title3.bold()).foregroundStyle(.green)} }
                }.storageAnalysisCard()
                VStack(alignment:.leading,spacing:10){Label(language.text("Potential space to recover","Espace potentiellement récupérable"),systemImage:"internaldrive").font(.headline).foregroundStyle(.green);Text(size(intelligence.recoverableBytes)).font(.system(size:44,weight:.bold,design:.rounded));if intelligence.deviceCapacityBytes>0{Text(language.text("Available space could rise from \(size(intelligence.deviceAvailableBytes)) to about \(size(intelligence.projectedAvailableBytes)). Final iOS storage can differ because of system caches.","L’espace disponible pourrait passer de \(size(intelligence.deviceAvailableBytes)) à environ \(size(intelligence.projectedAvailableBytes)). Le stockage final d’iOS peut varier à cause des caches système.")).font(.subheadline).foregroundStyle(.secondary)}}.storageAnalysisCard()
                if intelligence.isScanning { HStack(spacing:12){ProgressView();Text(language.text("Analyzing your photo library…","Analyse de votre photothèque…")).foregroundStyle(.secondary)}.storageAnalysisCard() }
                else if intelligence.categories.isEmpty { VStack(alignment:.leading,spacing:12){Label(language.text("Ready to analyze","Prêt à analyser"),systemImage:"chart.bar.doc.horizontal").font(.headline);Text(language.text("Analysis stays on this iPhone. Media is not uploaded just to calculate results.","L’analyse reste sur cet iPhone. Les médias ne sont pas envoyés dans le cloud uniquement pour calculer les résultats.")).font(.subheadline).foregroundStyle(.secondary);Button{Task{await intelligence.scan()}}label:{Label(language.text("Analyze storage","Analyser le stockage"),systemImage:"chart.bar.doc.horizontal").frame(maxWidth:.infinity).frame(height:42)}.buttonStyle(.borderedProminent)}.storageAnalysisCard() }
                else {
                    Text(language.text("What takes space","Ce qui prend de la place")).font(.title2.bold())
                    VStack(spacing:0){ForEach(Array(intelligence.categories.enumerated()),id:\.element.id){index,category in Button{selectedCategory=category.kind}label:{HStack(spacing:13){Image(systemName:icon(category.kind)).font(.system(size:18,weight:.semibold)).frame(width:38,height:38).background(Color.blue.opacity(0.11),in:RoundedRectangle(cornerRadius:11));VStack(alignment:.leading,spacing:3){Text(title(category.kind)).fontWeight(.semibold).foregroundStyle(.primary);Text("\(category.count.formatted()) "+language.text("items","éléments")).font(.caption).foregroundStyle(.secondary)};Spacer();Text(size(category.bytes)).fontWeight(.bold).foregroundStyle(.primary);Image(systemName:"chevron.right").font(.caption.bold()).foregroundStyle(.tertiary)}.padding(.vertical,13)}.buttonStyle(.plain);if index<intelligence.categories.count-1{Divider().padding(.leading,51)}}}.padding(.horizontal,16).storageAnalysisCard(padding:0)
                    if !intelligence.largestItems.isEmpty{Button{showLargest=true}label:{HStack{VStack(alignment:.leading,spacing:4){Text(language.text("Largest files","Fichiers les plus lourds")).font(.title2.bold()).foregroundStyle(.primary);Text(language.text("Open the Top 50 and choose exactly what to protect","Ouvrez le Top 50 et choisissez exactement quoi protéger")).font(.caption).foregroundStyle(.secondary)};Spacer();Image(systemName:"chevron.right").foregroundStyle(.secondary)}}.buttonStyle(.plain).storageAnalysisCard()}
                    Button{Task{await intelligence.scan()}}label:{Label(language.text("Analyze again","Analyser à nouveau"),systemImage:"arrow.clockwise").frame(maxWidth:.infinity).frame(height:42)}.buttonStyle(.bordered)
                }
            }.padding(20).padding(.bottom,80)
        }
        .background(LiberonsTheme.canvas).navigationTitle(language.text("Storage","Stockage")).navigationBarTitleDisplayMode(.inline)
        .task{intelligence.refreshDeviceStorage();if intelligence.categories.isEmpty{await intelligence.scan()}}
        .sheet(item:Binding(get:{selectedCategory.map(CategorySelection.init)},set:{selectedCategory=$0?.kind})){selection in selectionSheet(title(selection.kind),items:intelligence.items(for:selection.kind))}
        .sheet(isPresented:$showLargest){selectionSheet(language.text("Largest files","Fichiers les plus lourds"),items:intelligence.largestItems)}
        .sheet(isPresented:$showFreeOffer){freeSpaceOffer}
    }

    @ViewBuilder private func selectionSheet(_ title:String,items:[StorageInsightItem])->some View{
        NavigationStack{VStack(spacing:0){List(items){item in Button{toggle(item.id)}label:{HStack{Image(systemName:selectedIDs.contains(item.id) ? "checkmark.circle.fill":"circle").foregroundStyle(selectedIDs.contains(item.id) ? .blue:.secondary);InsightItemRow(item:item,language:language)}}.buttonStyle(.plain)}.listStyle(.plain);if !selectedIDs.isEmpty{VStack(spacing:9){HStack{Text("\(selectedIDs.count) "+language.text("selected","sélectionné(s)"));Spacer();Text(size(selectedBytes)).fontWeight(.bold)};Button{let ids=Array(selectedIDs);Task{await backup.backup(localIdentifiers:ids);let protected=backup.newlyProtectedLocalIdentifiers;selectedIDs.subtract(protected);guard !protected.isEmpty else{return};await cleaner.prepareExact(localIdentifiers:protected);if !cleaner.selectedLocalIdentifiers.isEmpty{showFreeOffer=true}}}label:{HStack{if backup.isRunning{ProgressView().tint(.white)};Label(backup.isRunning ? language.text("Protecting…","Protection…"):language.text("Protect selected with Libérons","Protéger la sélection avec Libérons"),systemImage:"icloud.and.arrow.up.fill")}.frame(maxWidth:.infinity).frame(height:44)}.buttonStyle(.borderedProminent).disabled(backup.isRunning);Text(language.text("Nothing is removed during protection. Libérons verifies the cloud copy first.","Rien n’est supprimé pendant la protection. Libérons vérifie d’abord la copie cloud.")).font(.caption).foregroundStyle(.secondary)}.padding(16).background(.bar)}}.navigationTitle(title).navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItem(placement:.topBarTrailing){Button(language.text("Select all","Tout sélectionner")){selectedIDs.formUnion(items.map(\.id))}}}}.presentationDragIndicator(.visible)
    }

    private var freeSpaceOffer: some View {
        NavigationStack{VStack(alignment:.leading,spacing:22){ZStack{RoundedRectangle(cornerRadius:22).fill(Color.green.opacity(0.12)).frame(width:72,height:72);Image(systemName:"checkmark.shield.fill").font(.system(size:31,weight:.semibold)).foregroundStyle(.green)};Text(language.text("Protected. Ready to free space.","Protégé. Prêt à libérer de l’espace.")).font(.largeTitle.bold());Text(language.text("Libérons confirmed these cloud copies before offering to remove the originals from this iPhone.","Libérons a confirmé ces copies cloud avant de proposer de retirer les originaux de cet iPhone.")).foregroundStyle(.secondary);VStack(spacing:0){offerRow(language.text("Verified items","Éléments vérifiés"),"\(cleaner.selectedLocalIdentifiers.count)");Divider();offerRow(language.text("Space you can free","Espace libérable"),freeSize);Divider();offerRow(language.text("Cloud copies","Copies cloud"),language.text("Remain protected","Restent protégées"))}.padding(.horizontal,18).background(LiberonsTheme.insetCard,in:RoundedRectangle(cornerRadius:20));Label(language.text("Apple Photos will ask for the final deletion confirmation. You can cancel there and nothing will be removed.","Photos demandera la confirmation finale de suppression. Vous pourrez annuler et rien ne sera retiré."),systemImage:"hand.raised.fill").font(.footnote).foregroundStyle(.secondary);Spacer();Button(role:.destructive){Task{await cleaner.deletePreparedFromIPhone();intelligence.refreshDeviceStorage();await intelligence.scan();if cleaner.selectedLocalIdentifiers.isEmpty{showFreeOffer=false}}}label:{HStack{if cleaner.isDeleting{ProgressView().tint(.white)};Text(language.text("Free \(freeSize) from this iPhone","Libérer \(freeSize) de cet iPhone")).fontWeight(.bold)}.frame(maxWidth:.infinity).frame(height:48)}.buttonStyle(.borderedProminent).disabled(cleaner.isDeleting);Button(language.text("Keep originals on iPhone","Garder les originaux sur l’iPhone")){showFreeOffer=false}.frame(maxWidth:.infinity)}.padding(24).background(LiberonsTheme.canvas).navigationTitle(language.text("Free space","Libérer de l’espace")).navigationBarTitleDisplayMode(.inline)}.presentationDetents([.large]).presentationDragIndicator(.visible)
    }

    private func offerRow(_ title:String,_ value:String)->some View{HStack{Text(title);Spacer();Text(value).fontWeight(.semibold).multilineTextAlignment(.trailing)}.padding(.vertical,15)}
    private func toggle(_ id:String){if selectedIDs.contains(id){selectedIDs.remove(id)}else{selectedIDs.insert(id)}}
    private func size(_ bytes:Int64)->String{bytes<=0 ? language.text("0 KB","0 Ko"):ByteCountFormatter.string(fromByteCount:bytes,countStyle:.file)}
    private func title(_ kind:StorageInsightItem.Kind)->String{switch kind{case .screenshot:return language.text("Screenshots","Captures d’écran");case .video:return language.text("Videos","Vidéos");case .largeVideo:return language.text("Large videos","Vidéos volumineuses");case .longVideo:return language.text("Long videos","Vidéos longues");case .slowMotion:return language.text("Slow motion","Ralenti");case .timeLapse:return "Time-lapse";case .livePhoto:return "Live Photos";case .rawPhoto:return "RAW";case .video4K:return language.text("4K videos","Vidéos 4K");case .other:return language.text("Other large files","Autres fichiers volumineux")}}
    private func icon(_ kind:StorageInsightItem.Kind)->String{switch kind{case .screenshot:return "iphone.gen3";case .video,.largeVideo,.longVideo,.video4K:return "video.fill";case .slowMotion:return "slowmo";case .timeLapse:return "timelapse";case .livePhoto:return "livephoto";case .rawPhoto:return "camera.aperture";case .other:return "doc.fill"}}
}

private struct CategorySelection:Identifiable{let kind:StorageInsightItem.Kind;var id:StorageInsightItem.Kind{kind}}
private struct InsightItemRow:View{let item:StorageInsightItem;@ObservedObject var language:LanguageStore;var body:some View{HStack(spacing:13){ZStack{RoundedRectangle(cornerRadius:11).fill(Color.secondary.opacity(0.10)).frame(width:38,height:38);Image(systemName:item.duration>0 ? "play.fill":"photo.fill").foregroundStyle(.secondary)};VStack(alignment:.leading,spacing:3){Text(item.duration>0 ? language.text("Video","Vidéo"):language.text("Photo","Photo")).fontWeight(.semibold);HStack(spacing:6){if item.duration>0{Text(duration(item.duration))};Text("\(item.pixelWidth)×\(item.pixelHeight)")}.font(.caption).foregroundStyle(.secondary)};Spacer();Text(ByteCountFormatter.string(fromByteCount:item.bytes,countStyle:.file)).fontWeight(.bold)}.padding(.vertical,8)};private func duration(_ seconds:TimeInterval)->String{let v=max(0,Int(seconds.rounded()));return v>=3600 ? String(format:"%d:%02d:%02d",v/3600,(v%3600)/60,v%60):String(format:"%d:%02d",v/60,v%60)}}
private extension View{func storageAnalysisCard(padding:CGFloat=18)->some View{self.padding(padding).frame(maxWidth:.infinity,alignment:.leading).background(LiberonsTheme.card,in:RoundedRectangle(cornerRadius:24,style:.continuous)).shadow(color:.black.opacity(0.035),radius:14,y:5)}}
